create extension if not exists pgcrypto;
create table if not exists public.members(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text,referral_code text unique,referred_by uuid references public.members(id),role text not null default 'member' check(role in('member','admin')),created_at timestamptz not null default now());
create table if not exists public.deposits(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,amount numeric(14,2) not null check(amount>0),status text not null default 'pending' check(status in('pending','approved','rejected')),payment_reference text,deposited_at timestamptz not null default now(),approved_at timestamptz);
create table if not exists public.investments(id uuid primary key default gen_random_uuid(),investment_name text not null,description text,amount_invested numeric(14,2) not null check(amount_invested>0),purchase_date date not null default current_date,status text not null default 'active' check(status in('planned','active','sold','cancelled')),created_at timestamptz not null default now());
create table if not exists public.stock(id uuid primary key default gen_random_uuid(),investment_id uuid references public.investments(id) on delete set null,item_name text not null,quantity numeric(14,2) not null check(quantity>0),purchase_cost numeric(14,2) not null check(purchase_cost>=0),expected_sale_value numeric(14,2),remaining_quantity numeric(14,2),created_at timestamptz not null default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),stock_id uuid references public.stock(id) on delete set null,quantity numeric(14,2) not null check(quantity>0),sale_amount numeric(14,2) not null check(sale_amount>=0),expenses numeric(14,2) not null default 0 check(expenses>=0),sale_date date not null default current_date,notes text,created_at timestamptz not null default now());
create table if not exists public.profit_distributions(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,investment_id uuid references public.investments(id) on delete set null,contribution_base numeric(14,2) not null default 0,profit_amount numeric(14,2) not null default 0,distributed_at timestamptz not null default now());
create table if not exists public.withdrawals(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,amount numeric(14,2) not null check(amount>0),status text not null default 'pending' check(status in('pending','approved','rejected','paid')),payment_reference text,requested_at timestamptz not null default now(),processed_at timestamptz);
create table if not exists public.referrals(id uuid primary key default gen_random_uuid(),referrer_id uuid not null references public.members(id) on delete cascade,referred_member_id uuid not null references public.members(id) on delete cascade,status text not null default 'registered' check(status in('registered','qualified')),created_at timestamptz not null default now(),unique(referrer_id,referred_member_id));
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),member_id uuid references public.members(id) on delete set null,transaction_type text not null check(transaction_type in('deposit','withdrawal','profit','investment','sale','referral')),amount numeric(14,2) not null default 0,reference_id uuid,description text,created_at timestamptz not null default now());
create index if not exists idx_deposits_member on public.deposits(member_id);create index if not exists idx_withdrawals_member on public.withdrawals(member_id);create index if not exists idx_profit_member on public.profit_distributions(member_id);create index if not exists idx_transactions_member on public.transactions(member_id);create index if not exists idx_referrals_referrer on public.referrals(referrer_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.members(id,full_name,referral_code) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Member'),upper(substr(replace(new.id::text,'-',''),1,8))) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.members where id=auth.uid() and role='admin'); $$;
alter table public.members enable row level security;alter table public.deposits enable row level security;alter table public.investments enable row level security;alter table public.stock enable row level security;alter table public.sales enable row level security;alter table public.profit_distributions enable row level security;alter table public.withdrawals enable row level security;alter table public.referrals enable row level security;alter table public.transactions enable row level security;
do $$ declare r record; begin for r in select policyname,tablename from pg_policies where schemaname='public' and tablename in('members','deposits','investments','stock','sales','profit_distributions','withdrawals','referrals','transactions') loop execute format('drop policy if exists %I on public.%I',r.policyname,r.tablename); end loop; end $$;
create policy members_self_or_admin on public.members for select to authenticated using(auth.uid()=id or public.is_admin());create policy members_self_update on public.members for update to authenticated using(auth.uid()=id or public.is_admin()) with check(auth.uid()=id or public.is_admin());
create policy deposits_self_select on public.deposits for select to authenticated using(auth.uid()=member_id or public.is_admin());create policy deposits_self_insert on public.deposits for insert to authenticated with check(auth.uid()=member_id);create policy deposits_admin_update on public.deposits for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy investments_admin_all on public.investments for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy stock_admin_all on public.stock for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy sales_admin_all on public.sales for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy profits_self_or_admin_select on public.profit_distributions for select to authenticated using(auth.uid()=member_id or public.is_admin());create policy profits_admin_insert on public.profit_distributions for insert to authenticated with check(public.is_admin());
create policy withdrawals_self_or_admin_select on public.withdrawals for select to authenticated using(auth.uid()=member_id or public.is_admin());create policy withdrawals_self_insert on public.withdrawals for insert to authenticated with check(auth.uid()=member_id);create policy withdrawals_admin_update on public.withdrawals for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy referrals_self_or_admin_select on public.referrals for select to authenticated using(auth.uid()=referrer_id or auth.uid()=referred_member_id or public.is_admin());create policy referrals_admin_all on public.referrals for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy transactions_self_or_admin_select on public.transactions for select to authenticated using(auth.uid()=member_id or public.is_admin());create policy transactions_admin_all on public.transactions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.reduce_stock_after_sale() returns trigger language plpgsql security definer set search_path=public as $$ declare current_qty numeric; begin if new.stock_id is null then return new; end if; select remaining_quantity into current_qty from public.stock where id=new.stock_id for update; if current_qty is null then raise exception 'Stock item not found'; end if; if new.quantity>current_qty then raise exception 'Sale quantity exceeds remaining stock'; end if; update public.stock set remaining_quantity=current_qty-new.quantity where id=new.stock_id; if current_qty-new.quantity=0 then update public.investments set status='sold' where id=(select investment_id from public.stock where id=new.stock_id); end if; return new; end; $$;
drop trigger if exists trg_reduce_stock_after_sale on public.sales;create trigger trg_reduce_stock_after_sale after insert on public.sales for each row execute function public.reduce_stock_after_sale();
create or replace function public.log_deposit_approval() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.status is distinct from new.status and new.status='approved' then insert into public.transactions(member_id,transaction_type,amount,reference_id,description) values(new.member_id,'deposit',new.amount,new.id,'Deposit approved'); elsif old.status is distinct from new.status and new.status='rejected' then insert into public.transactions(member_id,transaction_type,amount,reference_id,description) values(new.member_id,'deposit',0,new.id,'Deposit rejected'); end if; return new; end; $$;
drop trigger if exists trg_log_deposit_approval on public.deposits;create trigger trg_log_deposit_approval after update of status on public.deposits for each row execute function public.log_deposit_approval();
create or replace function public.log_withdrawal_update() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.status is distinct from new.status and new.status='paid' then insert into public.transactions(member_id,transaction_type,amount,reference_id,description) values(new.member_id,'withdrawal',-new.amount,new.id,'Withdrawal paid'); elsif old.status is distinct from new.status and new.status='rejected' then insert into public.transactions(member_id,transaction_type,amount,reference_id,description) values(new.member_id,'withdrawal',0,new.id,'Withdrawal rejected'); end if; return new; end; $$;
drop trigger if exists trg_log_withdrawal_update on public.withdrawals;create trigger trg_log_withdrawal_update after update of status on public.withdrawals for each row execute function public.log_withdrawal_update();
create or replace function public.log_profit_distribution() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.transactions(member_id,transaction_type,amount,reference_id,description) values(new.member_id,'profit',new.profit_amount,new.id,'Profit distributed'); return new; end; $$;
drop trigger if exists trg_log_profit_distribution on public.profit_distributions;create trigger trg_log_profit_distribution after insert on public.profit_distributions for each row execute function public.log_profit_distribution();
